"""Every question restated in our own words (Ian, 2026-11-02: the questions
are paraphrased so nothing is copied from the papers). The numbers, the
count of choices and their order are kept exactly, because the written
solutions refer to them by letter and value. A stem may carry a short
<ol class="sol-sub" type="i"> for the (i)/(ii) statement questions."""

def SUB(*items):
    return '<ol class="sol-sub" type="i">' + "".join("<li>%s</li>" % i for i in items) + "</ol>"

PQ = ["Price rises and quantity increases", "Price rises and quantity decreases",
      "Price falls and quantity increases", "Price falls and quantity decreases"]
NONE = "None of these"
PRICE_Q_BLANK = "What happens to the equilibrium price and quantity?"
FIGQ = "Which of the four figures shows what happens?"
FIGS = ["Figure A", "Figure B", "Figure C", "Figure D"]
STMT2 = ["Both statements hold", "Only the first holds", "Only the second holds", "Neither holds"]
STMT2b = ["Only the first holds", "Only the second holds", "Both statements hold", "Neither holds"]

P = {}

